from review import card,save,DATE
def b(title,text,citation=None):
 d=dict(title=title,text=text)
 if citation:d['citation']=citation
 return d
def summary(sentences,refs):
 return dict(sentences=sentences,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=refs)

i='TCS-2783';_,c=card(i);refs=c['references'];refs[0]['locator']='DISC 2022, article 37: Section 3.2, Definitions 6–7, pp. 9–10, and Theorem 8. The source uses “girth s” to mean no cycle shorter than s, not equality of the shortest cycle length.'
refs.append(dict(id='spanners2026',title='Unconditional Lower Bounds for Degree Fault Tolerant Spanners',authors='Greg Bodwin, Aleksey Lopez',year=2026,url='https://arxiv.org/abs/2607.07576',locator='Preprint v1, 8 July 2026: Section 1.1 states the girth conjecture and confirms that only k=1,2,3,5 are known; Section 1.3 explains that its unconditional degree-fault-tolerant spanner lower bounds do not prove the girth conjecture.'))
save(i,dict(
 title='Erdős’s girth conjecture: dense graphs without short cycles',
 formal='For every integer k≥1, do there exist constants c_k>0 and N_k such that, for every integer n≥N_k, some simple undirected graph G on exactly n vertices has at least c_k n^{1+1/k} edges and contains no cycle of length less than 2k+2? Equivalently, is M_{2k+2}(n)=Ω_k(n^{1+1/k}) for every fixed k, where M_s(n) is the maximum number of edges in an n-vertex graph with no cycle shorter than s?',
 definitions='A simple undirected graph consists of a finite vertex set and a set of unordered pairs of distinct vertices; loops and repeated edges are not allowed. A cycle of length ℓ≥3 has ℓ distinct vertices and the edges joining them cyclically. The girth is the length of the shortest cycle, and is +∞ for a forest. Thus “girth at least 2k+2” forbids every cycle of lengths 3,…,2k+1, including non-induced cycles. M_s(n) is a maximum over all such graphs on the vertex set {1,…,n}; connectedness, regularity and efficient construction are not required. The quantifier order is ∀k ∃c_k,N_k ∀n≥N_k ∃G. Constants may depend on k, but not on n; k remains fixed as n tends to infinity. The target is the stated constant-factor asymptotic density, not merely n^{1+1/k−o(1)}, nor a claim for an arbitrarily sparse subsequence of n. This at-least-girth convention reproduces the source’s definition.',
 question_type='yes_no',answer_criterion='Prove the displayed existence claim for every fixed integer k, or refute it for at least one fixed k. Refutation means that no positive c_k and threshold N_k work at that k; a construction for only selected k or a smaller exponent does not settle the universal conjecture.',
 context_blocks=[b('The density allowed by excluding cycles','Known extremal upper bounds give M_{2k+2}(n)=O_k(n^{1+1/k}). The conjecture asks whether forbidding all these short cycles still permits that many edges up to a constant factor.','primary'),b('Equivalent odd and even girth thresholds','Using threshold 2k+1 instead of 2k+2 gives an equivalent asymptotic conjecture: a graph has a bipartite subgraph with at least half its edges, and that subgraph has no odd cycles. This equivalence changes neither the exponent nor the fixed-k target.','primary'),b('Only some parameters are settled','The cases k=1,2,3,5 are known. The July 2026 spanner paper still lists exactly those cases; the next missing parameter k=4 asks for Ω(n^{5/4}) edges with girth at least 10.','spanners2026'),b('Consequences for routing and distance preservation','The source uses these graphs to establish conditional lower bounds on the memory needed by routing schemes with small stretch. More generally, the conjecture controls sharpness of size-versus-stretch bounds for graph spanners.','primary'),b('A recent unconditional application does not settle the graph conjecture','The 2026 preprint removes this assumption for a particular model of spanners tolerating edge failures of bounded degree. It explicitly distinguishes that result from constructing graphs of the girth and density required here.','spanners2026')],
 why='A central extremal graph question with direct consequences for compact routing and graph sparsification: it asks whether the standard density obstruction from short cycles is asymptotically tight at every fixed scale.',
 references=refs,progress=[dict(date='2022',text='The routing paper records the known k=1,2,3,5 cases and uses the full conjecture for higher-stretch space lower bounds.',citation='primary'),dict(date='2026-07-08',text='A new spanner preprint still states the full girth conjecture as open and proves a separate degree-fault-tolerant lower bound unconditionally.',citation='spanners2026')],
 status='source_open',status_note='Read the source definitions and routing use, then checked the July 2026 primary discussion and subsequent searches through 12 September 2026. The later spanner result does not resolve the girth conjecture; no further settled k was found.',model_self_contained=True,requires_context=False,
 importance=dict(score=c['importance']['score'],method='editorial',reason='A general extremal obstruction underlying sharp routing and distance-sparsification tradeoffs. Existing score retained rather than raised by this formulation review.',assessed_on=DATE),review_note='Restored 1+1/k, the all-sufficiently-large-n quantifier and the source’s at-least-girth convention. Separated the 2026 application from a resolution.',
 working_summary=summary(['The girth conjecture asks for dense graphs with every short cycle forbidden.','For each fixed k, the target is Ω(n^{1+1/k}) edges and girth at least 2k+2.','The lower bound must hold for every sufficiently large n, with constants depending on k.','The known cases are k=1,2,3,5, as still recorded in July 2026.','A resolution would sharpen fundamental lower bounds for routing and graph spanners.'],['primary','spanners2026'])
 ),notes=['Restored the missing reciprocal in the density exponent.','Specified simple graphs, all forbidden cycle lengths, and the exact asymptotic quantifiers.','Checked the recent spanner result and retained the distinction between that application and the conjecture.'],checked_sources=[r['url'] for r in refs])

i='TCS-2804';_,c=card(i);refs=c['references'];refs[0]['locator']='IPEC 2022, article 6: Section 2.2 defines XNLP and parameterized logspace reductions; Conjecture 14 on p. 15 gives the simultaneous n^{f(k)}-time, f(k)n^c-space obstruction.'
refs.append(dict(id='linear2025',title='XNLP-Completeness for Parameterized Problems on Graphs with a Linear Structure',authors='Hans L. Bodlaender, Carla Groenland, Hugo Jacob, Lars Jaffke, Paloma T. Lima',year=2025,url='https://doi.org/10.1007/s00453-024-01274-9',pdf_url='https://research-portal.uu.nl/ws/portalfiles/portal/261652374/s00453-024-01274-9.pdf',locator='Algorithmica 87, pp. 465–506; online 4 November 2024. Conjecture 1 on p. 467 retains the same simultaneous time-space statement; Sections 3.1–3.2 define the reduction conventions.'))
save(i,dict(
 title='The Slice-wise Polynomial Space Conjecture for XNLP-hard problems',
 formal='Is it true that no XNLP-hard parameterized decision problem has a single deterministic algorithm with both worst-case time (n+2)^{f(k)} and working space f(k)(n+2)^c, for any total computable function f:N→N and any absolute constant c? Here k is the parameter, n is the bit length of the ordinary input, and both resource bounds must hold on the same execution. Hardness uses parameterized logspace many-one reductions defined below.',
 definitions='A parameterized decision problem Q is a subset of {0,1}*×N, with input (x,k), n=|x| and k supplied in binary. XNLP consists of those Q decided by one nondeterministic multitape Turing machine using time g(k)(n+2)^a and working space g(k)log₂(n+2) for some total computable g and constant a, simultaneously on every branch. An input is accepted exactly when some branch accepts; all branches halt within the bound. The input tape is read-only and excluded from working space, which counts visited cells on the fixed finite-alphabet work tapes. A parameterized logspace reduction Q₁≤Q₂ is a deterministic halting transducer mapping (x,k) to (y,k′), preserving the yes/no answer, with k′≤h(k) for a total computable h and space h(k)+C log₂(n+2) for an absolute C. Its output is write-only and is not counted as working space. Q is XNLP-hard when every problem in XNLP has such a reduction to Q. In the conjectured forbidden deterministic algorithm there is no randomness, oracle or advice, and a single program handles all parameters. Constants, including c and the code computing f, are fixed for that program; f may grow arbitrarily fast but must be computable. Using different computable functions in the time and space bounds is equivalent, since one common f can dominate both. Replacing n by n+2 only handles short inputs. Slice-wise polynomial time allows its exponent to depend on k; the conjectured space bound permits dependence on k only in a multiplicative factor.',
 question_type='yes_no',answer_criterion='Prove the simultaneous resource obstruction for every XNLP-hard problem, or refute it by an XNLP-hard problem and one uniform deterministic algorithm satisfying both bounds for explicit computable f and fixed c. A space bound achieved by a different algorithm, a time bound with a superpolynomial exponent in n at fixed k, or a result for only bounded parameter values does not meet the criterion.',
 context_blocks=[b('Why time and memory have to be considered together','Parameterized dynamic programs often store tables of size n^{O(k)} and run in a comparable amount of time. Allowing a larger exponent in time does not automatically show whether the memory exponent can be made independent of k.','linear2025'),b('XNLP captures a small-space nondeterministic description','Its machines use only a parameter-dependent multiple of log n working space while running in fixed-parameter polynomial time. Many problems on graphs with linear decompositions are complete for this class.','linear2025'),b('What the conjecture rules out','The target would prohibit all deterministic algorithms with a fixed polynomial space exponent while retaining polynomial time on each fixed-parameter slice. It is a simultaneous tradeoff conjecture, not a claim that the problems cannot be solved in polynomial space with unrestricted time.','primary'),b('Later completeness results still use the conjecture','The Algorithmica paper establishes XNLP-completeness for several familiar graph problems and explicitly retains this time-space assertion as Conjecture 1. Such classifications transfer the conjectured obstruction; they do not prove it.','linear2025')],
 why='Would explain a broad barrier to reducing the memory of parameterized dynamic programming while keeping polynomial time for each fixed parameter, connecting practical table-size tradeoffs with a uniform complexity-class obstruction.',
 references=refs,progress=[dict(date='2022',text='Conjecture 14 states the simultaneous time-space obstruction and relates it to earlier work of Pilipczuk and Wrochna.',citation='primary'),dict(date='2025',text='The journal study of linear graph structure retains the statement as Conjecture 1 while proving new XNLP-completeness results.',citation='linear2025')],status='source_open',status_note='Read the source’s resource/reduction definitions and the retained Algorithmica conjecture. Later-result searches through 12 September 2026, including 2026 XALP and scheduling classifications, found no resolution of the stated obstruction.',model_self_contained=True,requires_context=False,
 importance=dict(score=c['importance']['score'],method='editorial',reason='A class-wide hypothesis about simultaneous memory and time, with consequences for many parameterized graph algorithms. Existing score retained.',assessed_on=DATE),review_note='Reconstructed the complete bound and made its determinism, uniformity, common resource functions, parameter dependence and hardness reductions explicit.',
 working_summary=summary(['XNLP describes parameterized problems with short nondeterministic working memory and fixed-parameter polynomial running time.','The conjecture forbids deterministic algorithms for XNLP-hard problems with both slice-wise polynomial time and a fixed polynomial space exponent.','One algorithm must meet both guarantees on every input.','The parameter may affect the time exponent and the space multiplier, but not the space exponent.','Later completeness results retain this as a conjecture that would explain memory barriers in dynamic programming.'],['primary','linear2025'])
 ),notes=['Restored the simultaneous n^{f(k)} time and f(k)n^c space bounds.','Defined XNLP, parameterized logspace hardness and uniform deterministic resource conventions.','Retained the all-problems conjecture and distinguished later completeness results from its resolution.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2605.03727','https://www.sciencedirect.com/science/article/pii/S0166218X26000466'])
